import { readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";

const source = new URL("../docs/advisor-core.md", import.meta.url);
const raw = await readFile(source, "utf8");
const text = raw.split(/\r?\n/).filter((line) => !["→ 流月", "→ 流日", "→ 流時"].includes(line.trim())).join("\n").trim();
const core = {
  sourceName: "八字命理顧問_命盤分析前必讀主核心義.md",
  sourceSha256: createHash("sha256").update(raw).digest("hex"),
  text
};
await writeFile(new URL("../advisor-core.js", import.meta.url),
  "// Generated by scripts/build-advisor-core.mjs from docs/advisor-core.md.\n" +
  "(function (root) {\n  const core = " + JSON.stringify(core, null, 2) + ";\n" +
  "  if (typeof module === \"object\" && module.exports) module.exports = core;\n" +
  "  else root.BaziAdvisorCore = Object.freeze(core);\n" +
  "})(typeof globalThis !== \"undefined\" ? globalThis : this);\n");
